// src/index.js
import React, { useRef, useEffect } from 'react';
import { render } from 'react-dom';
import { ComboBox } from 'carbon-components-react';
import 'carbon-components/css/carbon-components.min.css';

const items = [
  { id: 'option-1', text: 'Option 1' },
  { id: 'option-2', text: 'Option 2' },
];

function App() {
  const comboRef = useRef(null);

  useEffect(() => {
    // This will log 'null' and React will warn in console
    console.log('ComboBox ref:', comboRef.current);
  }, []);

  return (
    <div style={{ padding: '2rem' }}>
      <h2>ComboBox with a ref</h2>
      <ComboBox
        id="example-combobox"
        items={items}
        itemToString={item => (item ? item.text : '')}
        placeholder="Filter options"
        titleText="Test ComboBox"
        helperText="You should see a console warning and ref.current === null"
        ref={comboRef}  // <-- attaching ref triggers warning
      />
    </div>
  );
}

render(<App />, document.getElementById('root'));
